  function sourcePhrase(text){
    if(!text)return text;
    if(L.en[text]!==undefined||Object.values(L).some(dict=>dict[text]!==undefined))return text;
    for(const dict of Object.values(L)){for(const [source,value] of Object.entries(dict)){if(value===text)return source}}
    return text;
  }
  function translatePattern(text){
    const source=sourcePhrase(text),dict=L[lang]||{};
    if(dict[source])return dict[source];
    if(lang==="en")return source;
    let m=source.match(/^(\d+) (item|items)$/);if(m)return `${m[1]} ${t(Number(m[1])===1?"item":"items")}`;
    m=source.match(/^(\d+) styles$/);if(m)return `${m[1]} ${t("styles")}`;
    m=source.match(/^Size (.+)$/);if(m)return `${t("Size")} ${m[1]}`;
    m=source.match(/^Package (.+) · (\d+) pcs$/);if(m)return `${t("Package")} ${t(m[1])} · ${m[2]} ${t("pcs")}`;
    m=source.match(/^(.+) · (\d+) pcs$/);if(m)return `${t(m[1])} · ${m[2]} ${t("pcs")}`;
    m=source.match(/^(.+) \/ pc$/);if(m)return `${m[1]} / ${t("pc")}`;
    m=source.match(/^(.+) \/ pc · (.+) package$/);if(m)return `${m[1]} / ${t("pc")} · ${m[2]} ${t("package")}`;
    m=source.match(/^(.+) added to your bag$/);if(m)return lang==="uz"?`${m[1]} savatingizga qo‘shildi`:`${m[1]} добавлено в корзину`;
    m=source.match(/^Save (.+)$/);if(m)return lang==="uz"?`${m[1]} saqlash`:`Сохранить ${m[1]}`;
    m=source.match(/^(.+?)\s+Continue with (Google|Apple)$/);if(m)return `${m[1]} ${t(`Continue with ${m[2]}`)}`;
    m=source.match(/^Language: (EN|UZ|RU)$/);if(m)return lang==="uz"?`Til: ${m[1]}`:lang==="ru"?`Язык: ${m[1]}`:source;
    m=source.match(/^Order (.+)$/);if(m)return lang==="uz"?`Buyurtma ${m[1]}`:lang==="ru"?`Заказ ${m[1]}`:source;
    m=source.match(/^Automatic size mix: (.+)$/);if(m)return `${t("Automatic size mix")}: ${m[1]}`;
    m=source.match(/^Qadoq: (.+) per size · Qop: (.+) per size$/);if(m)return lang==="uz"?`Qadoq: har o‘lchamdan ${m[1]} · Qop: har o‘lchamdan ${m[2]}`:`Упаковка: ${m[1]} на размер · Мешок: ${m[2]} на размер`;
    return source;
  }
  const t = (key) => translatePattern(key);
  function translateTextNodes(root){
    const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode(node){const parent=node.parentElement;if(!parent||["SCRIPT","STYLE","SVG","IMG","INPUT","TEXTAREA"].includes(parent.tagName))return NodeFilter.FILTER_REJECT;return node.nodeValue.trim()?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT}});
    const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
    nodes.forEach(node=>{const raw=node.nodeValue.trim(),translated=t(raw);if(translated!==raw)node.nodeValue=node.nodeValue.replace(raw,translated)});
  }
  function translateVisible(){
    document.documentElement.lang=lang;
    const control=$(".lang-control");if(control){control.querySelector("small").textContent=lang.toUpperCase();control.setAttribute("aria-label",t("Language")+": "+lang.toUpperCase())}
    translateTextNodes(document.body);
    $$("[placeholder]").forEach(el=>el.placeholder=t(el.placeholder));
    $$("[aria-label]").forEach(el=>el.setAttribute("aria-label",t(el.getAttribute("aria-label"))));
  }
  const href = (params={}) => {
    if(location.pathname==="/preview")return "/preview" + (Object.keys(params).length ? "?"+new URLSearchParams(params) : "");
    return "/" + (Object.keys(params).length ? "?"+new URLSearchParams(params) : "");
  };
  function toast(msg){const el=$("[data-toast]");el.textContent=msg;el.classList.add("is-on");clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove("is-on"),2200)}
  function navigate(url){history.pushState({},"",url);render();scrollTo({top:0,behavior:"smooth"})}
  function suppressMega(trigger){if(!trigger)return;trigger.classList.add("is-suppressed");const release=()=>{trigger.classList.remove("is-suppressed");trigger.removeEventListener("pointerleave",release)};trigger.addEventListener("pointerleave",release)}
  function closeHeaderMenus(link){const head=$(".site-head");head?.classList.remove("is-menu");suppressMega(link?.closest(".mega-trigger"))}
  function productCard(p){const wished=read("milana-preview-wish",[]).includes(p.id);const choices=p.order_units?.length?p.order_units.map(u=>u.label):(p.sizes||[]).slice(0,5);return `<article class="product-card" data-product="${p.id}"><div class="product-media">${p.tag?`<span class="badge">${p.tag==="bestseller"?"Best seller":p.tag}</span>`:""}<button class="wish${wished?" is-on":""}" data-wish="${p.id}" aria-label="Save ${esc(p.name)}"><svg><use href="#icon-heart"/></svg></button><a href="${href({view:"product",slug:p.slug})}" data-link><img src="${esc(image(p))}" alt="${esc(p.name)}" loading="lazy"></a><div class="quick"><div class="quick__sizes">${choices.map((s,i)=>`<button class="${i===0?"is-on":""}" data-quick-size="${esc(s)}">${esc(s)}</button>`).join("")}</div><button class="quick__add" data-add="${p.id}">Quick add</button></div></div><div class="product-info"><div><h3><a href="${href({view:"product",slug:p.slug})}" data-link>${esc(p.name)}</a></h3><p>${money(p.price)} / pc</p></div><small>${esc(p.model_no||localized(p.fabric)||p.category||"Milana collection")}</small></div></article>`}
  async function init(){try{const [pr,sr]=await Promise.all([fetch("/api/products?limit=100"),fetch("/api/settings")]);const api=await pr.json();settings=await sr.json();products=Array.isArray(api)?api:[]}catch{products=[]}updateCartCount();render();syncHeaderState()}
  function render(){const q=route();document.body.className=q.view?"view-light":"view-home";$(".site-head").classList.remove("is-menu");if(q.view==="shop")renderShop(q);else if(q.view==="product"){renderProduct(q.slug);enhanceWholesaleProduct(q.slug)}else if(q.view==="auth"){renderAuth();applyCurrentBrandAuth()}else{renderHome();applyCurrentBrandHome()}translateVisible();startInlineVideos($("#view"));$("#view").focus({preventScroll:true})}
  function applyCurrentBrandHome(){const video=$(".hero video"),source=video?.querySelector("source");if(video){video.poster="/lounge_wear_user.webp";if(source)source.src="https://d8j0ntlcm91z4.cloudfront.net/user_34eZBNjNLgypc1pRns2x3gmtdUD/hf_20260705_031050_9ff123e7-ca25-4aa3-b430-ca21602a0b02.mp4";video.load();video.play?.().catch(()=>{})}const h1=$(".hero h1"),lead=$(".hero__copy>p"),eyebrow=$(".hero .eyebrow");if(h1)h1.textContent="Softness and elegance. In every touch.";if(lead)lead.textContent="The current Milana identity, upgraded with a faster path from inspiration to wholesale order.";if(eyebrow)eyebrow.textContent="Milana Premium · Andijan";mountWardrobe();mountBestsellers()}
  function enhanceWholesaleProduct(slug){const p=products.find(x=>x.slug===slug)||products[0];if(!p)return;const gallery=$(".gallery");if(gallery&&!gallery.classList.contains("nike-gallery"))gallery.innerHTML=(p.images||[]).map(u=>mediaTile(u,p)).join("");const title=$(".size-head span"),guide=$("[data-size-guide]"),sizes=$(".sizes"),inventory=$(".inventory"),add=$(".pdp-add"),fit=$(".fit-card"),price=$(".price"),ugc=$(".ugc img");if(title)title.textContent="Choose order format";if(guide)guide.textContent="Size mix guide";if(sizes)sizes.innerHTML=(p.order_units||[{label:"Qadoq",pieces:6},{label:"Qop",pieces:60}]).map((u,i)=>`<button class="${i===0?"is-on":""}" data-pdp-size="${esc(u.label)}">${esc(u.label)} · ${u.pieces} pcs</button>`).join("");if(inventory)inventory.textContent="Availability and dispatch are confirmed by a Milana manager";if(add)add.textContent="Add wholesale package to bag";if(fit)fit.innerHTML=`<strong>Automatic size mix: ${(p.sizes||[]).join(", ")}</strong><span>Every package is distributed evenly across the available sizes.</span><div class="fit-meter"><i></i><i></i><i></i></div><small>Qadoq: 1 per size · Qop: 10 per size</small>`;if(price)price.textContent=`${money(p.price)} / pc`;if(ugc)ugc.src="/lounge_wear_user.webp"}
  function applyCurrentBrandAuth(){const image=$(".auth-visual img"),title=$(".auth-visual h1");if(image)image.src="/lounge_wear_user.webp";if(title)title.textContent="Milana membership, made simpler."}
  function mountBestsellers(){const editorial=$(".editorial"),section=editorial?.closest(".section");if(!section)return;const best=products.filter(p=>p.tag==="bestseller"),cats=[...new Set(best.map(p=>p.category).filter(Boolean))];section.className="bestsellers-zone";section.dataset.bestFilter="all";section.dataset.bestSort="rank";section.innerHTML=`<header class="bestsellers-head"><div><span class="eyebrow">Milana customer favourites</span><h2>Bestsellers</h2><p>The proven wholesale styles customers return to.</p></div><a class="text-link" href="${href({view:"shop",tag:"bestseller"})}" data-link>View all bestsellers</a></header><div class="bestsellers-filters"><div><button class="is-on" data-best-filter="all">All</button>${cats.map(c=>`<button data-best-filter="${esc(c)}">${esc(c)}</button>`).join("")}</div><label>Sort <select data-best-sort><option value="rank">Bestseller rank</option><option value="rating">Top rated</option><option value="price">Price: low to high</option></select></label></div><div class="bestsellers-grid" data-bestsellers-grid></div>`;section.addEventListener("click",e=>{const filter=e.target.closest("[data-best-filter]");if(!filter)return;section.dataset.bestFilter=filter.dataset.bestFilter;$$('[data-best-filter]',section).forEach(button=>button.classList.toggle("is-on",button===filter));renderBestsellers(section)});$("[data-best-sort]",section).addEventListener("change",e=>{section.dataset.bestSort=e.target.value;renderBestsellers(section)});renderBestsellers(section)}
  function renderBestsellers(section){let list=products.filter(p=>p.tag==="bestseller");if(section.dataset.bestFilter!=="all")list=list.filter(p=>p.category===section.dataset.bestFilter);if(section.dataset.bestSort==="rating")list.sort((a,b)=>(b.rating||0)-(a.rating||0));if(section.dataset.bestSort==="price")list.sort((a,b)=>a.price-b.price);$("[data-bestsellers-grid]",section).innerHTML=list.map((p,i)=>bestsellerCard(p,i)).join("")}
  function bestsellerCard(p,index){const wished=read("milana-preview-wish",[]).includes(p.id),units=p.order_units||[{label:"Qadoq",pieces:6},{label:"Qop",pieces:60}],alt=p.images?.[1];return `<article class="product-card bestseller-card" data-product="${p.id}"><div class="product-media"><span class="bestseller-rank">#${String(index+1).padStart(2,"0")} <b>Best seller</b></span><button class="wish${wished?" is-on":""}" data-wish="${p.id}" aria-label="Save ${esc(p.name)}"><svg><use href="#icon-heart"/></svg></button><a href="${href({view:"product",slug:p.slug})}" data-link><img class="bestseller-primary" src="${esc(image(p))}" alt="${esc(p.name)}" loading="lazy">${alt?`<img class="bestseller-alt" src="${esc(alt)}" alt="" loading="lazy">`:""}</a><div class="quick"><div class="quick__sizes">${units.map((u,i)=>`<button class="${i===0?"is-on":""}" data-quick-size="${esc(u.label)}">${esc(u.label)} · ${u.pieces}</button>`).join("")}</div><button class="quick__add" data-add="${p.id}">Quick add</button></div></div><div class="bestseller-info"><div class="bestseller-title"><div><span>${esc(p.model_no||p.category)}</span><h3><a href="${href({view:"product",slug:p.slug})}" data-link>${esc(p.name)}</a></h3></div><strong>${money(p.price)} / pc</strong></div><div class="bestseller-proof"><span>★ ${Number(p.rating||0).toFixed(1)}</span><i>Current bestseller</i>${p.variant?`<em><b style="background:${p.variant.toLowerCase().includes("turquoise")?"#57aeb1":"#aaa"}"></b>${esc(p.variant)}</em>`:""}</div></div></article>`}
  function mountWardrobe(){const section=$(".section--tight");if(!section||!products.length)return;wardrobeItems=[...products,...products,...products];wardrobeIndex=products.length;section.className="wardrobe-zone";section.innerHTML=`<div class="wardrobe-heading"><span class="eyebrow">Drag to explore</span><h2>The Wardrobe</h2></div><div class="wardrobe-stage" data-wardrobe-stage><div class="wardrobe-track">${wardrobeItems.map((p,i)=>`<button type="button" class="wardrobe-card" data-wardrobe-card="${i}" aria-label="View ${esc(p.name)} ${esc(p.model_no||"")}"><img src="${esc(image(p))}" alt="${esc(p.name)}"><span><b>${esc(p.name)}</b><small>${esc(p.model_no||p.category)}</small></span></button>`).join("")}</div></div><div class="wardrobe-meta" data-wardrobe-meta></div><p class="wardrobe-hint"><span>←</span> Drag the wardrobe <span>→</span></p>`;const stage=$("[data-wardrobe-stage]",section);stage.addEventListener("pointerdown",e=>{wardrobeDragging=true;wardrobeDidDrag=false;wardrobeStartX=e.clientX;wardrobeDragX=0;stage.classList.add("is-dragging");stage.setPointerCapture?.(e.pointerId)});stage.addEventListener("pointermove",e=>{if(!wardrobeDragging)return;wardrobeDragX=e.clientX-wardrobeStartX;if(Math.abs(wardrobeDragX)>8)wardrobeDidDrag=true;renderWardrobe()});const finish=e=>{if(!wardrobeDragging)return;wardrobeDragging=false;stage.classList.remove("is-dragging");if(Math.abs(wardrobeDragX)>42)wardrobeIndex=mod(wardrobeIndex-Math.sign(wardrobeDragX),wardrobeItems.length);wardrobeDragX=0;renderWardrobe();stage.releasePointerCapture?.(e.pointerId)};stage.addEventListener("pointerup",finish);stage.addEventListener("pointercancel",finish);stage.addEventListener("keydown",e=>{if(e.key==="ArrowLeft"){wardrobeIndex=mod(wardrobeIndex-1,wardrobeItems.length);renderWardrobe()}if(e.key==="ArrowRight"){wardrobeIndex=mod(wardrobeIndex+1,wardrobeItems.length);renderWardrobe()}});$$("[data-wardrobe-card]",section).forEach(card=>card.addEventListener("click",()=>{const i=Number(card.dataset.wardrobeCard);if(wardrobeDidDrag){wardrobeDidDrag=false;return}if(i===wardrobeIndex){const p=wardrobeItems[i];navigate(href({view:"product",slug:p.slug}));return}wardrobeIndex=i;renderWardrobe()}));renderWardrobe()}
  function mod(n,m){return((n%m)+m)%m}
  function renderWardrobe(){const cards=$$("[data-wardrobe-card]"),meta=$("[data-wardrobe-meta]");if(!cards.length)return;const n=cards.length,step=Math.min(205,innerWidth*.47);cards.forEach((card,i)=>{let d=i-wardrobeIndex;if(d>n/2)d-=n;if(d<-n/2)d+=n;const a=Math.abs(d),scale=a===0?1:a===1?.79:a===2?.61:.56,y=a===0?0:a===1?38:a===2?72:82,visible=a<=4;card.style.transform=`translate3d(calc(-50% + ${d*step+wardrobeDragX}px),${y}px,0) scale(${scale})`;card.style.zIndex=String(20-Math.min(a,9));card.style.opacity=visible?"1":"0";card.style.pointerEvents=visible?"auto":"none";card.classList.toggle("is-active",a===0)});const p=wardrobeItems[wardrobeIndex];if(meta&&p)meta.innerHTML=`<span>${esc(p.tag==="new"?"New arrival":"Milana bestseller")}</span><h3>${esc(p.name)} <small>${esc(p.model_no||"")}</small></h3><p>${esc(localized(p.fabric)||"")} · ${money(p.price)} / pc</p><a href="${href({view:"product",slug:p.slug})}" data-link>View product ↗</a>`}
  function closeZoom(){const layer=$("[data-zoom]"),video=$("[data-zoom-video]");video?.pause?.();if(video)video.removeAttribute("src");layer?.classList.remove("is-on")}
