  function renderAuth(){authStage="start";$("#view").innerHTML=`<section class="auth-view"><div class="auth-visual"><img src="/assets/img/lb-couple.jpg" alt="Milana collection"><div><span class="eyebrow">Milana members</span><h1>More ease. Less admin.</h1><p>Save your fit, see orders and get early access to new drops.</p></div></div><div class="auth-panel"><div class="auth-card" data-auth-card></div></div></section>`;drawAuth()}
  function drawAuth(){const card=$("[data-auth-card]");if(!card)return;if(authStage==="start"){card.innerHTML=`<span class="eyebrow">Account access</span><h2>Welcome to Milana.</h2><p>Social sign-in appears first when its provider is configured. Local preview uses email.</p><div class="social-stack"><button class="social-button" disabled>G &nbsp; Continue with Google <small>Setup required</small></button><button class="social-button" disabled>● &nbsp; Continue with Apple <small>Setup required</small></button></div><div class="divider">or continue with email</div><form data-auth-email><label class="field"><span>Email address</span><input name="email" type="email" autocomplete="email" required placeholder="you@example.com"></label><button class="auth-primary">Continue</button></form><button class="auth-secondary" data-guest>Continue as guest</button><button class="auth-secondary" data-signup-start>New here? Create an account</button><p class="auth-msg" data-auth-msg></p>`}else if(authStage==="login"){card.innerHTML=`<button class="auth-back" data-auth-reset>← ${esc(authEmail)}</button><span class="eyebrow">One step left</span><h2>Good to see you.</h2><form data-password-login><label class="field"><span>Password</span><input name="password" type="password" autocomplete="current-password" minlength="8" required autofocus></label><button class="auth-primary">Sign in</button></form><div class="divider">or</div><button class="social-button" data-code-start>Email me a one-time code</button><p class="auth-msg" data-auth-msg></p>`}else if(authStage==="code"){card.innerHTML=`<button class="auth-back" data-auth-reset>← ${esc(authEmail)}</button><span class="eyebrow">Passwordless sign-in</span><h2>Check your email.</h2><p>Enter the six-digit code. In local mode, the development code appears below.</p><form data-code-login><label class="field"><span>One-time code</span><input name="code" inputmode="numeric" maxlength="6" autocomplete="one-time-code" required autofocus></label><button class="auth-primary">Verify & sign in</button></form><p class="auth-msg" data-auth-msg></p>`}else if(authStage==="signup"){card.innerHTML=`<button class="auth-back" data-auth-reset>← Back to sign in</button><span class="eyebrow">Fast signup</span><h2>Create your account.</h2><p>Only the essentials now. Style and size preferences come after signup.</p><form data-signup><label class="field"><span>Email</span><input name="email" type="email" required></label><label class="field"><span>Full name</span><input name="name" required minlength="2"></label><label class="field"><span>Password</span><input name="password" type="password" minlength="8" required></label><label class="field"><span>Email code</span><input name="email_code" inputmode="numeric" maxlength="6" required></label><button type="button" class="social-button" data-signup-code>Send email code</button><button class="auth-primary">Create account</button></form><p class="auth-msg" data-auth-msg></p>`}else if(authStage==="preferences"){card.innerHTML=`<span class="eyebrow">Account created</span><h2>Make Milana yours.</h2><p>This optional step happens after signup. Skip it whenever you like.</p><strong>Your usual sizes</strong><div class="preference-chips">${["XS","S","M","L","XL","XXL"].map(x=>`<button data-pref="${x}">${x}</button>`).join("")}</div><strong>What do you shop for?</strong><div class="preference-chips">${["Women","Men","Kids","Wholesale"].map(x=>`<button data-pref="${x}">${x}</button>`).join("")}</div><button class="auth-primary" data-pref-save>Save and shop</button><button class="auth-secondary" data-guest>Skip for now</button>`}}
