  function addToCart(id,source){const p=products.find(x=>x.id===Number(id));if(!p)return;const card=source?.closest("[data-product]");const size=(card?.querySelector("[data-quick-size].is-on")?.dataset.quickSize||$("[data-pdp-size].is-on")?.dataset.pdpSize||p.order_units?.[0]?.label||p.sizes?.[0]||"One size").split(" · ")[0];const unit=p.order_units?.find(u=>u.label===size)||{pieces:1,unit_type:size.toLowerCase()};const existing=cart.find(x=>x.id===p.id&&x.size===size);existing?existing.qty++:cart.push({id:p.id,slug:p.slug,name:p.name,image:image(p),unit_price:p.price,price:p.price*(unit.pieces||1),size,unit_type:unit.unit_type||size.toLowerCase(),pieces:unit.pieces||1,qty:1});store(CART_KEY,cart);updateCartCount();toast(t(`${p.name} · ${size} added to your bag`))}
