  document.addEventListener("submit",async e=>{if(e.target.matches("[data-newsletter]")){e.preventDefault();const email=e.target.querySelector('input[type="email"]')?.value.trim();try{await post("/api/newsletter",{email,lang,source:"next_storefront"});$("[data-newsletter-note]").textContent=t("You’re on the Milana list.")}catch(err){$("[data-newsletter-note]").textContent=err.message==="invalid_email"?t("Please enter a valid email."):t(err.message)}return}if(e.target.matches("[data-auth-email]")){e.preventDefault();authEmail=e.target.elements.email.value.trim().toLowerCase();authStage="login";drawAuth();translateVisible();return}if(e.target.matches("[data-password-login]")){e.preventDefault();try{await post("/api/auth/signin",{email:authEmail,password:e.target.elements.password.value});toast(t("Welcome back"));navigate(href({view:"shop"}))}catch(err){$("[data-auth-msg]").textContent=err.message==="wrong_credentials"?t("Email or password is incorrect."):t(err.message)}return}if(e.target.matches("[data-code-login]")){e.preventDefault();try{await post("/api/auth/passwordless",{email:authEmail,code:e.target.elements.code.value});toast(t("Signed in securely"));navigate(href({view:"shop"}))}catch(err){$("[data-auth-msg]").textContent=t(err.message)}return}if(e.target.matches("[data-signup]")){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{await post("/api/auth/signup",{...d,account_type:"individual",terms:true,lang});authStage="preferences";drawAuth();translateVisible()}catch(err){$("[data-auth-msg]").textContent=t(err.message)}return}});
